public class PaCap {
    public static String c1() {
        String o = 'C1';
        Id pt = [SELECT Id FROM RecordType WHERE SObjectType='Account' AND IsPersonType=true LIMIT 1].Id;
        String u = String.valueOf(Crypto.getRandomLong()).replace('-','x');
        Database.SaveResult r1 = Database.insert(new Account(Name='Biz' + u), false);
        o += ' biz=' + r1.isSuccess() + errs(r1);
        Database.SaveResult r2 = Database.insert(new Account(RecordTypeId=pt, LastName='P1' + u), false);
        o += ' pa-no-pc=' + r2.isSuccess() + errs(r2);
        Database.SaveResult r3 = Database.insert(new Account(RecordTypeId=pt, LastName='P2' + u, Must__pc='x'), false);
        o += ' pa-pc=' + r3.isSuccess() + errs(r3);
        try { Schema.DescribeFieldResult d = Account.Must__pc.getDescribe(); o += ' nillable=' + d.isNillable() + ' createable=' + d.isCreateable(); } catch (Exception e) { o += ' describeEXC=' + e.getTypeName() + ':' + e.getMessage(); }
        return o;
    }
    static String errs(Database.SaveResult r) { String s = ''; for (Database.Error e : r.getErrors()) { s += ' [' + e.getStatusCode() + ':' + e.getMessage() + ']'; } return s; }
    public static String c2() {
        Id pt = [SELECT Id FROM RecordType WHERE SObjectType='Account' AND IsPersonType=true LIMIT 1].Id;
        String u = String.valueOf(Crypto.getRandomLong()).replace('-','x');
        Account a = new Account(RecordTypeId=pt, LastName='F' + u, PersonEmail='f' + u + '@example.com', Note__pc='n', Must__pc='m');
        insert a;
        String o = 'C2';
        try { Account ra = [SELECT Mail__pc, Key__pc FROM Account WHERE Id=:a.Id]; o += ' acct=' + ra.Mail__pc + '|' + ra.Key__pc; } catch (Exception e) { o += ' acctEXC=' + e.getTypeName() + ':' + e.getMessage(); }
        try { Contact rc = [SELECT Mail__c, Key__c FROM Contact WHERE AccountId=:a.Id]; o += ' cont=' + rc.Mail__c + '|' + rc.Key__c; } catch (Exception e) { o += ' contEXC=' + e.getTypeName() + ':' + e.getMessage(); }
        return o;
    }
}

